            std::string Helper::getCPPStyledContent(const ::fs::Path &path) {
                try {
                    std::ifstream file(path.toStr());
                    if (!file.is_open()) return "";
                    return std::string((std::istreambuf_iterator<char>(file)), (std::istreambuf_iterator<char>()));
                }
                catch(...) {
                    return "";
                }
            }

